def generate_report(data, format_type):
    """Generate a report from data in the specified format."""
    if format_type == "text":
        lines = []
        lines.append("REPORT")
        lines.append("======")
        lines.append("")
        if "title" in data:
            lines.append("Title: " + data["title"])
        if "author" in data:
            lines.append("Author: " + data["author"])
        lines.append("")
        if "items" in data:
            lines.append("Items:")
            for item in data["items"]:
                lines.append("  - " + item)
        lines.append("")
        if "summary" in data:
            lines.append("Summary: " + data["summary"])
        return "\n".join(lines)
    elif format_type == "html":
        lines = []
        lines.append("<html>")
        lines.append("<head><title>Report</title></head>")
        lines.append("<body>")
        if "title" in data:
            lines.append("<h1>" + data["title"] + "</h1>")
        if "author" in data:
            lines.append("<p>Author: " + data["author"] + "</p>")
        if "items" in data:
            lines.append("<ul>")
            for item in data["items"]:
                lines.append("<li>" + item + "</li>")
            lines.append("</ul>")
        if "summary" in data:
            lines.append("<p>" + data["summary"] + "</p>")
        lines.append("</body>")
        lines.append("</html>")
        return "\n".join(lines)
    elif format_type == "markdown":
        lines = []
        if "title" in data:
            lines.append("# " + data["title"])
            lines.append("")
        if "author" in data:
            lines.append("**Author:** " + data["author"])
            lines.append("")
        if "items" in data:
            lines.append("## Items")
            for item in data["items"]:
                lines.append("- " + item)
            lines.append("")
        if "summary" in data:
            lines.append("## Summary")
            lines.append(data["summary"])
        return "\n".join(lines)
    else:
        raise ValueError(f"Unknown format: {format_type}")

def generate_summary(data):
    """Generate a one-line summary string."""
    parts = []
    if "title" in data:
        parts.append(data["title"])
    if "author" in data:
        parts.append("by " + data["author"])
    if "items" in data:
        parts.append(str(len(data["items"])) + " items")
    if "summary" in data:
        parts.append(data["summary"])
    return " | ".join(parts)
