def tree_stats(root):
    """Get statistics about a tree."""
    total = sum_tree(root)
    count = count_nodes(root)
    depth = tree_depth(root)
    if count == 0:
        return {"total": 0, "count": 0, "average": 0, "depth": 0}
    return {"total": total, "count": count, "average": total / count, "depth": depth}

def find_max_value(node):
