def compare_trees(tree_a, tree_b):
    """Compare two trees and return differences."""
    stats_a = tree_stats(tree_a)
    stats_b = tree_stats(tree_b)
    diffs = {}
    for key in stats_a:
        if stats_a[key] != stats_b[key]:
            diffs[key] = {"a": stats_a[key], "b": stats_b[key]}
    return diffs
